// sRGB ICC profile ("sRGB built-in", 588 bytes, generated by LittleCMS via Pillow's
// ImageCms.createProfile('sRGB'); its copyright tag reads "No copyright, use freely").
// Embedded as an iCCP chunk so RIP software and Photoshop that look for an ICC profile see sRGB.
const B64 = ''

let cached: Uint8Array | null = null

export function srgbIccProfile(): Uint8Array {
  if (!cached) {
    const bin = atob(B64)
    cached = new Uint8Array(bin.length)
    for (let i = 0; i < bin.length; i++) cached[i] = bin.charCodeAt(i)
  }
  return cached
}
